dict(id="T15", task="1.4", stem=
"A market research firm needs Microsoft SQL Server on Amazon EC2 for a six-week project. It owns no SQL Server licenses it could move, and it will delete the servers when the project ends. Which licensing approach fits best?",
choices=[("Bring its own licenses to shared EC2 instances under License Mobility",0),("Buy new licenses from Microsoft and run them on Dedicated Hosts",0),("Use license-included instances, paying for SQL Server by the hour in the instance price",1),("Run SQL Server unlicensed, because AWS covers licensing for all software on EC2",0)],
expl="License-included instances add the license to the hourly price, with no long-term commitment, and AWS handles the license compliance; that suits short, changing work. Bringing your own license needs licenses you already own (and, for shared instances, active Software Assurance), which the firm doesn't have. Buying licenses and dedicated hardware for six weeks costs far more, and AWS doesn't license software you install yourself.",
links=[("13-moving-to-aws/04-the-business-case.md","License-included or bring your own license: who pays the software vendor")]),

dict(**{'id': 'T16', 'task': '1.4', 'stem': "A small accounting firm will run Windows Server on a few Amazon EC2 instances that it resizes often. It doesn't want to buy, track or prove compliance for Windows Server licenses itself, or to buy client access licenses. Which licensing approach fits?", 'choices': [('License-included Windows Server instances, paying for the license in the hourly price', 1), ('Its own Windows Server licenses on shared instances, under License Mobility', 0), ('Its own Windows Server licenses on Dedicated Hosts, tracked with AWS License Manager', 0), ('Unlicensed Windows Server, since AWS licenses all software on EC2', 0)], 'expl': "With license-included instances the hourly price covers Windows Server, AWS handles license compliance, no client access licenses are needed, and the firm can resize or stop at any time. Bringing its own licenses would make compliance the firm's job; Windows Server also isn't eligible for License Mobility, so its own licenses would need Dedicated Hosts.", 'links': [('13-moving-to-aws/04-the-business-case.md', 'License-included or bring your own license: who pays the software vendor')]}),

